    "consent.text1": "أنت تختار ما يمكن لـ VITA فعله لك. يمكنك تغيير أي إذن أو سحبه في أي وقت؛ ويوقف السحب العمل المرتبط به فورًا.",
    "consent.text2": "البحث: نبحث عن وظائف حقيقية تطابق بياناتك المؤكدة وتفضيلاتك. الإعداد: نُعدّ طلبات صادقة من بياناتك المؤكدة فقط. الإرسال: يمكن إرسال الطلبات إلى أصحاب العمل ضمن القواعد التي يحددها فريق VITA.",
    "consent.text3": "لا نختلق أبدًا مؤهلات أو خبرات أو لغات أو تصريح عمل، ولا نرسل أبدًا جواز سفر أو بطاقة هوية أو شهادة سوابق عدلية أو مستندًا طبيًا دون إذن منفصل منك لذلك الطلب.",
